<article class="post-card border {{ $post->is_pinned ? 'border-white hard' : 'border-silver-800' }} bg-pitch-900 p-5" data-post-id="{{ $post->id }}" data-sector="{{ $post->sector }}" data-tags="{{ strtolower(implode(' ', $post->tags ?? [])) }}" data-search="{{ strtolower($post->title.' '.$post->body.' '.implode(' ', $post->tags ?? [])) }}"><div class="mb-3 flex flex-wrap justify-between gap-2 text-[10px] text-silver-500"><span class="border border-silver-700 px-2 py-1">SECTOR // {{ $post->sector }}</span><span>{{ strtoupper($post->status) }} // {{ $post->created_at->diffForHumans() }}</span></div><h2 class="mb-2 font-oswald text-2xl uppercase">{{ $post->title }}</h2><p class="mb-4 text-xs leading-6 text-silver-400">{{ \Illuminate\Support\Str::limit($post->body, 260) }}</p>@if (count($post->tags ?? []))<div class="mb-4 flex flex-wrap gap-2 text-[10px]">@foreach($post->tags as $tag)<button class="tag-chip border border-silver-700 px-2 py-1 text-silver-400 hover:border-white hover:text-white" data-tag="{{ strtolower($tag) }}">#{{ strtolower($tag) }}</button>@endforeach</div>@endif @if (!empty($post->media)) <div class="media-strip mb-4 {{ count($post->media) === 2 ? 'grid grid-cols-2 gap-2' : 'grid grid-cols-3 gap-2' }}">@if (count($post->media) === 1)<img src="/posts/{{ basename($post->media[0]) }}" class="h-64 w-full border border-silver-700 object-cover" alt="attached media" loading="lazy">@elseif (count($post->media) === 2)@foreach($post->media as $m)<img src="/posts/{{ basename($m) }}" class="h-40 w-full border border-silver-700 object-cover" alt="attached media" loading="lazy">@endforeach@else @foreach(array_slice($post->media, 0, 3) as $m)<img src="/posts/{{ basename($m) }}" class="h-32 w-full border border-silver-700 object-cover" alt="attached media" loading="lazy">@endforeach @endif</div>@if(count($post->media) > 3)<p class="mb-4 text-[10px] tracking-widest text-silver-500">+{{ count($post->media) - 3 }} MORE ATTACHED — OPEN INTEL TO VIEW</p>@endif @endif <div class="flex items-center justify-between border-t border-silver-800 pt-3 text-[10px]"><span class="text-silver-500">BY <strong class="text-white">{{ strtoupper($post->author->name) }}</strong></span><span class="flex items-center gap-2"><button class="react-btn border border-silver-700 px-2 py-1 text-silver-400 hover:border-white hover:text-white" data-react="up" @if ($post->reactions->where('value','up')->where('user_id',auth()->id())->count()) style="color:#fff;border-color:#fff" @endif>&#9650; <span class="react-count">{{ $post->reactions->where('value','up')->count() }}</span></button><button class="react-btn border border-silver-700 px-2 py-1 text-silver-400 hover:border-white hover:text-white" data-react="down" @if ($post->reactions->where('value','down')->where('user_id',auth()->id())->count()) style="color:#fff;border-color:#fff" @endif>&#9660; <span class="react-count">{{ $post->reactions->where('value','down')->count() }}</span></button><button class="read-post border border-silver-700 px-3 py-1 hover:border-white" data-title="{{ $post->title }}" data-body="{{ $post->body }}" data-media="{{ implode(',', $post->media ?? []) }}">READ INTEL</button></span></div></article>
